reference_solution:
def combinationSum(candidates, target):
    cands = sorted(candidates)
    res, cur = [], []
    def bt(start, rem):
        if rem == 0:
            res.append(cur[:])
            return
        for i in range(start, len(cands)):
            if cands[i] > rem:
                break
            cur.append(cands[i])
            bt(i, rem - cands[i])
            cur.pop()
    bt(0, target)
    return res

brute_force_solution:
def combinationSum(candidates, target):
    out = []
    def go(i, rem, cur):
        if i == len(candidates):
            if rem == 0:
                out.append(cur[:])
            return
        c = candidates[i]
        for cnt in range(rem // c + 1):
            go(i + 1, rem - cnt * c, cur + [c] * cnt)
    go(0, target, [])
    return out

